import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Tabs, Tab } from 'carbon-components-react';

function App() {
  return (
    // Force the container to be narrow so that Tabs collapse into the dropdown variant
    <div style={{ width: 320, margin: '40px auto', border: '1px solid #ccc', padding: '16px' }}>
      <Tabs>
        <Tab id="tab-1" label="Tab label 1">
          <p>Content for first tab goes here.</p>
        </Tab>
        <Tab id="tab-2" label="Tab label 2">
          <p>Content for second tab goes here.</p>
        </Tab>
        <Tab id="tab-3" label="Tab label 3">
          <p>Content for third tab goes here.</p>
        </Tab>
        <Tab id="tab-4" label="Custom Label">
          <p>Content for custom tab goes here.</p>
        </Tab>
      </Tabs>
    </div>
  );
}

const root = document.getElementById('root') || document.body;
ReactDOM.render(<App />, root);

// To reproduce the dropdown variant in action:
// 1. Run this code in a React app that has carbon-components-react installed.
// 2. Observe the container is only 320px wide, so Tabs collapse to a dropdown.
// 3. Resize the browser wider than ~600px and you will see the default horizontal tab list instead.
